from research_helpers import source, assessment, record, scope, evidence, decision, write_batch

S = [
    source('src-thx-tcm', 'THX 1138', 'Turner Classic Movies', 'https://www.tcm.com/articles/140793/thx-1138', 'secondary_film_reference_indexed', 'Public factory-worker and robot-police description read', 'Human workers assemble the machines that enforce their society’s rules.', 'Robotic enforcement is not proof that industrial human work is unnecessary or that goods are provided independently of it.'),
    source('src-metropolis-reference', 'Metropolis 1927 film', 'Wikipedia contributors', 'https://en.wikipedia.org/wiki/Metropolis_(1927_film)', 'secondary_film_plot_reference_indexed', 'Public worker, robot and impersonation paragraphs read', 'Real industrial workers and a prototype used for social manipulation.', 'Potential labor replacement is not an implemented society-wide support system; a human/robot class metaphor is not a labor census.'),
    source('src-things-come-afi', 'Things to Come', 'American Film Institute Catalog', 'https://catalog.afi.com/Film/4300-THINGS-TO-COME', 'secondary_institutional_film_synopsis_indexed', 'Public 1970 and 2036 setting passages read', 'Everytown becomes a technologically advanced underground city by 2036.', 'Disease-free technocracy and reconstruction machinery do not establish actual household access or wage independence. No dates from the source novel are substituted.'),
    source('src-forbidden-planet-afi', 'Forbidden Planet', 'American Film Institute Catalog', 'https://catalog.afi.com/Film/51831-FORBIDDEN-PLANET', 'secondary_institutional_film_synopsis_indexed', 'Public twenty-year household, research and replicating-lunch passages read', 'Morbius and Altaira live with Robby, whose chemical laboratory reproduces food.', 'A two-human household is a deliberately narrow economic unit, not the whole United Planets civilization or an extant Krell society.'),
    source('src-robby-reference', 'Robby the Robot', 'Wikipedia contributors', 'https://en.wikipedia.org/wiki/Robby_the_Robot', 'secondary_film_character_reference_indexed', 'Public mechanical-servant, creator and household description read', 'Morbius builds and programs Robby from Krell-derived knowledge.', 'Nonhuman robot agency and safety constraints do not establish ownership independent of Morbius; later appearances of the prop/character are excluded.'),
    source('src-forbidden-planet-synthetic-dialogue', 'Forbidden Planet: Movie Script', 'Film dialogue transcribed by Springfield Springfield', 'https://www.springfieldspringfield.co.uk/movie_script.php?movie=forbidden-planet', 'primary_film_dialogue_transcription_indexed', 'Bounded public food-synthetic and household-service passages read', 'Food samples can be reproduced, and Robby supplies material household services.', 'No whole script or new film viewing. One displayed device does not prove every historical Krell citizen had unlimited access.'),
    source('src-earth-stood-still-1951-speech', 'The Day the Earth Stood Still: Klaatu’s speech', '1951 film dialogue, Wikiquote transcription', 'https://en.wikiquote.org/wiki/The_Day_the_Earth_Stood_Still_(1951_film)', 'primary_film_dialogue_transcription_indexed', 'Public robot-peace-enforcement speech read', 'Robots hold irrevocable power over aggression, allowing other pursuits.', 'Authority over aggression is not authority over all production, and peace is not evidence of labor-independent material provision.'),
    source('src-earth-stood-still-2008-reference', 'The Day the Earth Stood Still 2008 film', 'Wikipedia contributors', 'https://en.wikipedia.org/wiki/The_Day_the_Earth_Stood_Still_(2008_film)', 'secondary_film_plot_reference_indexed', 'Public Klaatu, GORT and environmental-intervention paragraphs read', 'An alien mission, destructive nanites and a halted intervention.', 'No civilian alien distribution system is depicted by these passages; the 1951 treaty is not imported.'),
    source('src-colossus-film-reference', 'Colossus: The Forbin Project', 'Wikipedia contributors', 'https://en.wikipedia.org/wiki/Colossus%3A_The_Forbin_Project', 'secondary_film_plot_reference_indexed', 'Public takeover and final promise passages read', 'World-control threats and a promise of future plenty.', 'The film’s threat/promise is not proof that a durable automatic support economy has been implemented. Novel sequels remain separate.'),
    source('src-westworld-1973-robots', 'Robot 1973', 'Westworld Wiki contributors', 'https://westworld.fandom.com/wiki/Robot_(1973)', 'secondary_film_lore_reference_indexed', 'Public resort-role and human-guest entries read', 'Android actors provide purchased park experiences.', 'Temporary paying tourists and working technicians are not a durable automation-funded resident society; HBO continuity is excluded.'),
    source('src-futureworld-afi', 'Futureworld', 'American Film Institute Catalog', 'https://catalog.afi.com/Film/55247-FUTUREWORLD', 'secondary_institutional_film_synopsis_indexed', 'Public resort-reopening, reporter and replacement-plot passages read', 'A resort and human-replacement conspiracy.', 'Robot doubles and corporate intrigue do not establish a civilian support economy; no whole film read/view claimed.')
]
s = ['src-forbidden-planet-afi', 'src-robby-reference', 'src-forbidden-planet-synthetic-dialogue']
R = [record('forbidden-planet-morbius-household', 'c0335', 'Forbidden Planet (Morbius’s robot-supported household)', 'Forbidden Planet', 'Morbius and Altaira’s continuing robotic-production household', ['movie'],
    scope('1956 film continuity', 'The established two-human household before the visiting crew and final destruction', 'Morbius and his living daughter Altaira', ['The visiting ship’s crew', 'Extinct Krell counted as current residents', 'Morbius’s deceased wife', 'A claim of United Planets-wide post-work rights']),
    'Morbius and Altaira have an implemented, continuing support arrangement rather than merely a large fortune. Robby reproduces food chemically and performs material household service, allowing the isolated pair to obtain necessities without earning wages or importing an ordinary workforce. The guarantee estimate is strong inside this two-person unit, while remaining conditional on a private household and its functioning machinery. It is not universal citizenship or proof that the surrounding civilization has ended work.\n\nMorbius designs, programs and commands the producer, so effective productive control is concentrated in one human. Robby’s intelligence and protective limits do not make the robot an independent economic ruler. Human work continues in another form: Morbius studies the Krell, and Altaira’s learning or animal care can also be useful activity. The central participation estimate treats her mainly recreational life as nonworking and Morbius as working, with a range allowing both to count as useful workers. That is a transparent two-person interpretation, not a general labor statistic. The later rescue and destruction of the planet end this particular arrangement.',
    {'guarantees': -0.7, 'control': 0.05, 'nonworking': 0.5},
    {'guarantees': assessment(-0.7, [-0.95, -0.35], 'medium', 'The continuing household has actual synthetic food and robotic service; no wage condition is depicted, but support remains privately controlled and not universally available.', s),
     'control': assessment(0.05, [0, 0.15], 'high', 'Morbius creates and programs Robby and directs its productive activity; safety constraints are not broad resident ownership.', s),
     'nonworking': assessment(0.5, [0, 0.5], 'low', 'For two living residents, Morbius’s sustained research means at least one works. The central estimate treats Altaira as primarily leisured; if her learning or care is sustained useful work, the fraction can be zero. This bounded role scenario is not canonical.', s)},
    1, s, [evidence('A continuing isolated household uses actual food replication and robotic service under Morbius’s command.', s, 'AFI household/lunch synopsis; Robby character and synthetic-food dialogue entries', 'institutional_film_reference_and_primary_dialogue')],
    ['A deliberately tiny household unit with actual production, distinct from a rich protagonist simply buying goods.', 'The participation estimate has a two-person denominator and cannot represent a whole country or species.', 'The scientist’s voluntary research and potentially useful care/learning still count as work.', 'No historical Krell entitlement or post-destruction future is inferred.'])]
D = [
    decision('c0331', 'boundary_case', 'THX 1138’s human workers perform actual industrial production.', ['src-thx-tcm'], analysis='Robot police and computer mediation do not establish unnecessary human work or general labor-independent access.', follow_up='Keep as a controlled-industrial-labor comparison.'),
    decision('c0332', 'boundary_case', 'Metropolis shows an exploited workforce and robot prototype rather than an implemented post-work support system.', ['src-metropolis-reference'], analysis='Potential replacement and robot impersonation are not realized universal automation or deliberate preservation of dispensable jobs.', follow_up='Keep as an industrial/automation-potential comparison.'),
    decision('c0333', 'needs_evidence', 'Everytown’s 2036 technological prosperity does not settle household distribution or labor independence.', ['src-things-come-afi'], analysis='The source verifies the film’s year and advanced city, but science, peace and disease control do not supply an economic constitution.', follow_up='Skip film/novel reconstruction; do not import different chronology or policies from Wells’s book.'),
    decision('c0334', 'needs_evidence', 'Krell thought-production technology does not establish a durable, generally accessible pre-extinction support arrangement.', ['src-forbidden-planet-afi', 'src-forbidden-planet-synthetic-dialogue'], analysis='A technological culmination and catastrophic outcome are not a verified long-lived entitlement system or a justified alien participation denominator.', follow_up='Skip speculative historical reconstruction; the living human household has its own narrower record.'),
    decision('c0335', 'included', 'The two-human household has actual continuing synthetic-food production and robotic service, with its limited unit disclosed.', s, society_id='forbidden-planet-morbius-household'),
    decision('c0336', 'needs_evidence', 'Robotic control of aggression does not establish the interplanetary society’s material provision system.', ['src-earth-stood-still-1951-speech'], analysis='Klaatu’s speech concerns enforcement and peace, not ordinary goods, ownership or labor participation. Absolute power in one jurisdiction is not authority over every productive function.', follow_up='Skip deeper lore reading.'),
    decision('c0337', 'boundary_case', 'The 2008 alien intervention is not a depicted civilian post-work society.', ['src-earth-stood-still-2008-reference'], analysis='Planetary destruction, preservation missions and a halted attack do not establish resident production and access. The earlier film’s treaty is a different continuity.', follow_up='Keep as an autonomous-enforcement comparison.'),
    decision('c0338', 'needs_evidence', 'Colossus establishes coercive control but only promises the material plenty needed for this lead.', ['src-colossus-film-reference'], analysis='Nuclear leverage and a future abundance speech do not demonstrate an already functioning labor-independent supply system; novel and film institutions are not combined.', follow_up='Skip sequel or novel reconstruction.'),
    decision('c0339', 'boundary_case', 'Delos supplies a purchased temporary leisure service, not a durable supported resident society.', ['src-westworld-1973-robots'], analysis='Android performance does not make paying tourists independent of outside income, and actual technical staff remain at work.', follow_up='Keep as a leisure-industry automation comparison.'),
    decision('c0340', 'boundary_case', 'Futureworld’s resort and replacement scheme do not establish a post-work civilian support order.', ['src-futureworld-afi'], analysis='Robot doubles and a corporate conspiracy change control risks without establishing distribution of necessities.', follow_up='Skip speculative extrapolation beyond the realized film plot.')
]
write_batch(53, [f'c{i:04}' for i in range(331, 341)], S, R, D, [
    'Ten reference-led film decisions and one deliberately tiny but materially explicit household record.',
    'Morbius’s actual continuing fabrication qualifies the limited unit; mere personal wealth would not. Its two-person participation scenario stays visible.',
    'Krell extinction does not prohibit historical research, but the short source does not establish a durable pre-extinction entitlement regime.',
    'Things to Come uses the verified film year 2036. Peace-enforcement power, promised abundance and temporary tourism are not universal economic arrangements.'
])
